#!/bin/bash
# GSE320507 full-data discoveries by event class, coverage-null-filtered (SUPPA2 not simulated)
set -euo pipefail
unset LOADEDMODULES; for v in $(compgen -A variable _ModuleTable); do unset "$v"; done
module load Python/3.12.3-GCCcore-13.3.0; source ~/venv/kinnex_py/bin/activate
cd ~/projects/tealeaf; export PYTHONPATH=$PWD
python extra_scripts/plot_discoveries_by_event.py --tealeaf-events analyses/pbmc/GSE320507_events/test_events.tsv.gz --suppa2 /gpfs/commons/home/daknowles/tealeaf_runs/pbmc/GSE320507/junction_benchmark/comparator_suppa_rmats/suppa2/full_data_tests.tsv.gz --suppa2-primer-aware /gpfs/commons/home/daknowles/tealeaf_runs/pbmc/GSE320507/junction_benchmark/comparator_suppa_rmats/suppa2_primer_aware/full_data_tests.tsv.gz --rmats /gpfs/commons/home/daknowles/tealeaf_runs/pbmc/GSE320507/junction_benchmark/comparator_suppa_rmats/rmats/full_data_tests.tsv.gz --majiq-tests /gpfs/commons/home/daknowles/tealeaf_runs/pbmc/GSE320507/junction_benchmark/majiq/tests/normalized --junction-table /gpfs/commons/home/daknowles/tealeaf_runs/pbmc/GSE320507/junction_benchmark/comparison/all_tests.tsv.gz --leafcutter-counts /gpfs/commons/home/daknowles/tealeaf_runs/pbmc/GSE320507/junction_benchmark/leafcutter/clustering/benchmark_perind_numers.counts.gz --junction-annotation /gpfs/commons/home/daknowles/tealeaf_runs/pbmc/GSE320507/junction_benchmark/pseudobulk_junctions_junctions.tsv.gz --contrasts common --majiq-coverage-null analyses/coverage_null_filter/pbmc/majiq_coverage_null_targeted.parquet --coverage-flagged analyses/coverage_null_filter/pbmc/flagged_full.tsv.gz --output docs/figures/discoveries_by_event_GSE320507.pdf
